const WORDS_PER_WEEK = 5;
const MAX_WEEK = 40;

// 精灵图布局（必须与 assets/sprite.jpg 实际尺寸、app.wxss 里 .sprite-img 的 1600%/1300% 保持一致）
const SPRITE = { cols: 16, rows: 13, cell: 112, src: "../../assets/sprite.jpg" };

function getWeekWords(week) {
  return WORDS.filter((w) => w.week === week).slice(0, WORDS_PER_WEEK);
}

function getWordById(id) {
  return WORDS.find((w) => w.id === id) || null;
}

module.exports = { WORDS, WORDS_PER_WEEK, MAX_WEEK, SPRITE, getWeekWords, getWordById };
